import zipfile,io,csv,re,collections,sqlite3,sys
sys.setrecursionlimit(10000)
z=zipfile.ZipFile('retrieval-log/session_2026-11-22-icf-umbrella-glossary/38776b09204984dc.zip')
txt=z.read('SimpleTabulation-ICF-en.txt').decode('utf-8-sig')
rows=list(csv.reader(io.StringIO(txt),delimiter='\t'))
hdr=rows[0]
R=[dict(zip(hdr,r)) for r in rows[1:]]
print('empty furi',sum(1 for r in R if not r['Foundation URI']),'empty parent',sum(1 for r in R if not r['Parent']), 'empty lin',sum(1 for r in R if not r['Linearization URI']))
e=[r for r in R if not r['Foundation URI']][:3]; print(e)
furi={r['Foundation URI']:r for r in R if r['Foundation URI']}
lin={r['Linearization URI']:r for r in R}
print('parent resolves via furi',sum(1 for r in R if r['Parent'] in furi),'via lin',sum(1 for r in R if r['Parent'] in lin), 'neither',[ (r['Code'],r['Parent']) for r in R if r['Parent'] and r['Parent'] not in furi and r['Parent'] not in lin][:5])
def par(r): return furi.get(r['Parent']) or lin.get(r['Parent'])
def clean(t): return re.sub(r'^(- )+','',t).strip()
kids=collections.defaultdict(list)
for r in R:
    p=par(r)
    if p: kids[id(p)].append(r)
def desc(r):
    out=[]
    for k in kids[id(r)]:
        out.append(k); out+=desc(k)
    return out
blocks=[r for r in R if r['ClassKind']=='block']
cats=[r for r in R if r['ClassKind']=='category']
c3=[r for r in cats if re.fullmatch(r'[bdes]\d{3}',r['Code'])]
span={}
for b in blocks:
    d=[x['Code'] for x in desc(b) if re.fullmatch(r'[bdes]\d{3}',x['Code'])]
    span[b['BlockId']]=(min(d),max(d),len(d)) if d else None
L23=[b for b in blocks if b['BlockId'].startswith(('BlockL2','BlockL3'))]
print('L2/L3',len(L23))
for b in blocks:
    if b['BlockId'] in('BlockL3-b75','BlockL2-b71','BlockL2-d91','BlockL3-d31','BlockL3-d33','BlockL3-d71') or re.search(r'-d[379]',b['BlockId']) or b['BlockId'].startswith('BlockL1') or not b['BlockId']:
        p=par(b)
        print(repr(b['BlockId']),clean(b['Title']),span[b['BlockId']],'parent',p['BlockId'] or clean(p['Title']),[(k['Code'] or k['BlockId']) for k in kids[id(b)]][:14])
print('none-span L23',[b['BlockId'] for b in L23 if span[b['BlockId']] is None])
sp=collections.defaultdict(list)
for b in L23: sp[span[b['BlockId']][:2]].append(b['BlockId']+':'+clean(b['Title']))
print('dup spans',{k:v for k,v in sp.items() if len(v)>1})
bid=collections.Counter(b['BlockId'] for b in blocks); print('dup blockids',[k for k,v in bid.items() if v>1])
np=[(r['Code'],(par(r) or {}).get('BlockId') or (par(r) or {}).get('Code')) for r in c3 if not par(r) or not par(r)['BlockId'].startswith(('BlockL2','BlockL3'))]
print('3-digit with non-L2/L3 parent',len(np),np[:20])
for b in L23:
    ks=kids[id(b)]
    if len(set(k['ClassKind'] for k in ks))>1: print('mixed',b['BlockId'],clean(b['Title']),[(k['Code'] or k['BlockId']) for k in ks])
# L2 blocks whose direct-category 3-digit children: does L2 span equal union? L2 with 3-digit direct children outside any L3
for b in L23:
    if b['BlockId'].startswith('BlockL2'):
        l3=[k for k in kids[id(b)] if k['ClassKind']=='block']
        dc=[k['Code'] for k in kids[id(b)] if k['ClassKind']=='category']
        if l3 and dc: print('L2 w/ both',b['BlockId'],dc)
codes={}
for r in cats:
    if r['Code'] in codes: print('dupcode',r['Code'])
    codes[r['Code']]=clean(r['Title'])
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
held=c.execute("select icf_code,title,title_source,is_range from base_icf").fetchall()
print('held singles',sum(1 for h in held if not h[3]),'missing in WHO',[h[0] for h in held if not h[3] and h[0] not in codes])
diff=[(h[0],h[1][:70],codes.get(h[0]),h[2]) for h in held if h[1] and h[1].lower()!=codes[h[0]].lower()]
print('differ ci',len(diff)); [print('  ',d) for d in diff]
print('case-only',[(h[0],h[1],codes[h[0]]) for h in held if h[1] and h[1]!=codes[h[0]] and h[1].lower()==codes[h[0]].lower()])
print('matching',[(h[0],h[1],codes[h[0]]) for h in held if h[1] and h[1].lower()==codes[h[0]].lower()])
for k in ['b210','b230','b265','b280','d910','d920','b164','b765']: print(k,codes.get(k))
print('counts',txt.count('b750-b789'),txt.count('b750–b789'),txt.count('d910'),)
print([ (b['BlockId'],clean(b['Title']),span[b['BlockId']]) for b in blocks if re.search('earing|Pain|ovement',b['Title'])])
# held deeper codes parents
for h in held:
    if not h[3] and len(h[0])>4:
        r=[x for x in cats if x['Code']==h[0]][0]; print('deeper',h[0],'parent',par(r)['Code'])
# all L2/L3 spans for compare to stored ranges
st={'d310','d330','d710','d910'}
print([(b['BlockId'],span[b['BlockId']]) for b in L23 if span[b['BlockId']][0] in st])
# residual 3-digit codes (e.g. d998/d999) under which parent
print([(r['Code'],clean(r['Title']),(par(r) or {}).get('BlockId')) for r in c3 if r['Code'] in('d998','d999','d929','d298','b798','b799','b789','b780')])
print('residual 3digit',sum(1 for r in c3 if r['IsResidual']=='True'))
